CREATE TABLE public.event_contract_drafts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL REFERENCES public.events(id) ON DELETE RESTRICT,
  version integer NOT NULL CHECK (version > 0),
  status text NOT NULL DEFAULT 'pendiente_validacion' CHECK (status IN ('pendiente_validacion','vigente')),
  content jsonb NOT NULL,
  note text,
  created_by uuid DEFAULT auth.uid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, version)
);
COMMENT ON TABLE public.event_contract_drafts IS 'Versioned, append-only, admin-only contract drafts per event. Never read by public or booking flows; a row is not in force until a separate explicit publication step.';
GRANT SELECT, INSERT ON public.event_contract_drafts TO authenticated;
GRANT ALL ON public.event_contract_drafts TO service_role;
ALTER TABLE public.event_contract_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_contract_drafts_admin_read ON public.event_contract_drafts FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_super_admin(auth.uid()));
CREATE POLICY event_contract_drafts_admin_insert ON public.event_contract_drafts FOR INSERT TO authenticated
  WITH CHECK ((public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_super_admin(auth.uid())) AND status = 'pendiente_validacion');
CREATE OR REPLACE FUNCTION public._event_contract_drafts_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN RAISE EXCEPTION 'event_contract_drafts es solo de alta: creá una nueva versión'; END $$;
CREATE TRIGGER event_contract_drafts_append_only BEFORE UPDATE OR DELETE ON public.event_contract_drafts
  FOR EACH ROW EXECUTE FUNCTION public._event_contract_drafts_append_only();
INSERT INTO public.event_contract_drafts (event_id, version, status, content, note) VALUES
('408a8eb8-fb62-4a50-ad6d-040bd5716797', 1, 'pendiente_validacion', $j${"model_event_id":"67b4e85d-b00b-4b74-9644-99458d948c65","sections":[{"key":"reserva_pagos","title":"1. Reserva y pagos","status":"pendiente_validacion","body":"El Camp completo se realiza del lunes 18 al domingo 24 de enero de 2027 (7 días, 6 noches, salida el domingo). La preinscripción no reserva cupo ni requiere pago. La plaza queda reservada únicamente cuando Ciclismo Reybaud confirma por escrito la disponibilidad de alojamiento y se acredita la seña. El importe de la seña, el plan de cuotas y la fecha límite del saldo se informarán antes de abrir las reservas [PENDIENTE: condiciones de seña y cuotas]."},{"key":"precio_inclusiones","title":"2. Precio e inclusiones del paquete","status":"pendiente_validacion","body":"Las tarifas son por ciclista y estimativas hasta la confirmación del hotel y del kit. Cada paquete incluye solo el tipo de alojamiento y la gastronomía indicados: habitación doble o individual con desayuno, almuerzo y cena; cabaña de 3 plazas con desayuno, almuerzo y cena; o cabaña de 3 plazas con desayuno y sin almuerzo ni cena. El desayuno en cabaña está sujeto a validación del hotel. Los servicios y detalles finales del kit se confirmarán antes de la reserva. La noche previa del domingo 17/01 puede solicitarse como opcional: su disponibilidad y precio se confirman aparte y no forman parte del paquete."},{"key":"habitaciones","title":"3. Habitaciones y distribución","status":"pendiente_validacion","body":"No se ofrecen habitaciones triples de hotel; las únicas plazas de a tres son cabañas. Las habitaciones y cabañas compartidas se asignan según disponibilidad, género y paquete contratado. Las solicitudes de compañero se consideran pero no se garantizan hasta la confirmación final del rooming."},{"key":"cancelaciones","title":"4. Cancelaciones, cambios y transferencia de cupo","status":"pendiente_validacion","body":"Las condiciones de cancelación, devolución y transferencia se informarán antes de abrir las reservas y se aceptarán junto con la reserva [PENDIENTE: texto validado]. Toda solicitud se realiza por escrito por los canales oficiales. Reprogramación: si condiciones meteorológicas adversas ponen en riesgo la seguridad, o si sobreviene una imposibilidad de realizar el camp, Ciclismo Reybaud podrá anunciar una nueva fecha. Las inscripciones se trasladarán a esa fecha sin pago adicional; cada participante recibirá aviso y podrá elegir mantener su lugar o solicitar el reintegro por el canal indicado."},{"key":"programa_clima","title":"5. Programa y clima","status":"pendiente_validacion","body":"Recorridos, horarios y actividades pueden ajustarse por clima, seguridad, estado de caminos, decisiones de autoridades o disponibilidad de proveedores. Ciclismo Reybaud prioriza la seguridad y procura ofrecer una alternativa equivalente."},{"key":"aptitud_equipo","title":"6. Aptitud física y equipo","status":"pendiente_validacion","body":"Cada participante declara condiciones de salud adecuadas y presenta apto médico vigente cuando se solicite. Es obligatorio usar casco, contar con una bicicleta en condiciones seguras y respetar las indicaciones del staff y las normas de tránsito."},{"key":"nivel","title":"7. Nivel ciclista","status":"pendiente_validacion","body":"El camp incluye salidas de ruta acordes al nivel informado por la organización. Cada persona debe informar lesiones, limitaciones, medicación relevante o cualquier condición que afecte su participación."},{"key":"dietas","title":"8. Alimentación y necesidades especiales","status":"pendiente_validacion","body":"Las necesidades alimentarias deben informarse dentro del plazo que se comunique al confirmar la reserva [PENDIENTE: fecha]. Se hará lo posible por contemplarlas, sin garantizar ausencia total de contaminación cruzada. En cabaña sin almuerzo ni cena, esas comidas quedan a cargo del participante."},{"key":"seguros","title":"9. Seguro y pertenencias","status":"pendiente_validacion","body":"Cada participante debe contar con obra social o prepaga y seguro de accidentes personales. Ciclismo Reybaud no responde por pérdida, robo o daño de bicicletas, equipos o pertenencias, salvo responsabilidad comprobable de la organización."},{"key":"convivencia","title":"10. Convivencia y conducta","status":"pendiente_validacion","body":"Se espera conducta respetuosa con participantes, staff, alojamiento, proveedores y comunidad local. La organización podrá limitar la participación de quien ponga en riesgo la seguridad o el normal desarrollo del camp."},{"key":"imagen","title":"11. Uso de imagen","status":"pendiente_validacion","body":"Podrán registrarse fotos y videos para comunicación de Ciclismo Reybaud. Quien no autorice el uso de su imagen debe informarlo por escrito antes del inicio."},{"key":"canales","title":"12. Canales oficiales","status":"pendiente_validacion","body":"Toda información válida sobre pagos, horarios, cambios, logística y reprogramaciones se comunica por los canales oficiales de Ciclismo Reybaud."}],"rescheduling":{"causes":{"clima_riesgo_seguridad":{"label":"Clima adverso con riesgo para la seguridad","forceMajeure":true,"note":"Requiere evidencia (pronóstico/alerta oficial) guardada con el aviso."},"imposibilidad_sobrevenida":{"label":"Imposibilidad sobrevenida ajena al organizador","forceMajeure":true,"note":"Requiere evidencia (autoridad, cierre, caso fortuito) guardada con el aviso."},"operativo_organizador":{"label":"Problema operativo del organizador","forceMajeure":false,"note":"No es fuerza mayor: reintegro íntegro y revisión legal de cualquier otra consecuencia."}},"procedure":["Admin registra causal, evidencia, fecha original y nueva fecha propuesta (borrador, sin ejecutar).","Revisión y aprobación explícita de un admin para la ejecución en lote.","Aviso a cada participante con fecha original, nueva fecha, motivo, opciones y canal de reintegro; se guarda la fecha del aviso.","Cada participante responde: mantener lugar en la nueva fecha o solicitar reintegro. No se impone la fecha sin posibilidad de respuesta.","El traslado mueve la misma reserva con sus pagos (sin pago adicional, sin duplicar reservas ni pagos), conservando historial.","Los reintegros se calculan sin deducciones automáticas y se ejecutan solo con aprobación manual."],"refund_rule":"Reintegro del total acreditado, sin deducciones automáticas; ejecución manual aprobada."},"internal_proposals":[{"key":"descuento_15_reintegro_post_reprogramacion","status":"propuesta_interna_bajo_validacion_legal","vigente":false,"publicable":false,"aplicaAutomaticamente":false,"text":"Preferencia comercial: si tras una reprogramación el participante pide devolución, retener 15%.","legalNote":"No vigente. Requiere revisión legal (Ley 24.240, arts. 10 bis y 37): podría ser abusiva, en especial si la causa es atribuible al organizador. Nunca aplicar a causales operativas del organizador."}],"reservation_flow":[{"key":"solicitud_pendiente","label":"Solicitud pendiente (preinscripción)"},{"key":"verificacion_alojamiento","label":"Verificación manual de alojamiento, cupo y fechas superpuestas"},{"key":"sena","label":"Seña acreditada"},{"key":"reserva_confirmada","label":"Reserva confirmada"},{"key":"cuotas","label":"Cuotas del saldo"},{"key":"terminos","label":"Aceptación de términos"},{"key":"rooming","label":"Rooming"}],"opening_blockers":[{"key":"inventario","label":"Inventario confirmado por el hotel: dobles, individuales y cabañas de 3 plazas"},{"key":"simultaneo","label":"Límite simultáneo de ciclistas 21–24/01 (camp completo + Mini) confirmado por hotel y vehículos"},{"key":"sena_cuotas","label":"Importe de seña, plan de cuotas y fecha límite del saldo"},{"key":"noche_extra","label":"Disponibilidad y precio de la noche extra del 17/01"},{"key":"reprogramacion","label":"Política de reprogramación revisada legalmente"},{"key":"cancelacion","label":"Texto de cancelación y transferencia validado"},{"key":"tarifas_kit","label":"Reconfirmación de tarifas y kit"}]}$j$::jsonb, 'Borrador inicial basado en San Luis 2026; no vigente');
INSERT INTO public.event_contract_drafts (event_id, version, status, content, note)
SELECT '5380df24-6bbf-4d25-81cd-a1ab2b41bd94', 1, 'pendiente_validacion',
  replace(replace(content::text,
    'El Camp completo se realiza del lunes 18 al domingo 24 de enero de 2027 (7 días, 6 noches, salida el domingo).',
    'El Mini Camp se realiza del jueves 21 al domingo 24 de enero de 2027 (4 días, 3 noches, salida el domingo).'),
    ' La noche previa del domingo 17/01 puede solicitarse como opcional: su disponibilidad y precio se confirman aparte y no forman parte del paquete.', '')::jsonb,
  'Borrador inicial basado en San Luis 2026; no vigente'
FROM public.event_contract_drafts WHERE event_id = '408a8eb8-fb62-4a50-ad6d-040bd5716797' AND version = 1;